// Ported from Limbophobia src/game/arrivalKit/geo.ts (same author): its texture painters only; the geometry and game code stay there.
// Generated by the material library's extractor and then kept by hand. Paints at 32 px per metre (src/gfx/mat/atlas.ts).

/** deterministic 0..1 hash */
export function hash3(x: number, y: number, z = 0): number {
  let h = Math.imul(Math.round(x * 1000) * 374761393 + Math.round(y * 1000) * 668265263 + Math.round(z * 1000) * 2246822519, 0x27d4eb2d);
  h ^= h >>> 15; h = Math.imul(h, 0x85ebca6b); h ^= h >>> 13;
  return ((h >>> 0) % 100000) / 100000;
}
